"""Shadow Ball drawn by code instead of generated by an image model: pixel art at 56x56 per frame, scaled 2x with no
smoothing (every art pixel is a 2x2 block, like Terraria's own sprites), only the 6 colors of the Ghost palette.
Follows art/vfx/prompts/fantasma.md (8. Shadow Ball), with one more orb frame so the ball spins while it flies.

Run: python3 tools/vfx/draw_shadow_ball.py   (from the repo root)
Writes Pokerraria/Assets/Moves/ShadowBall.png/.txt and a preview sheet on magenta in art/vfx/sheets/."""
import math
import random

import numpy as np
from PIL import Image

# Ghost palette, lightest to darkest (art/vfx/prompts/README.md)
WHITE, LIGHT, MID, BASE, DARK, OUTLINE = range(1, 7)
COLORS = {WHITE: "#FFFFFF", LIGHT: "#E9D5FF", MID: "#A855F7", BASE: "#7E22CE", DARK: "#4C1D95", OUTLINE: "#240046"}
N = 56          # art pixels per frame side
SCALE = 2       # screen pixels per art pixel
C = (N - 1) / 2  # frame center


def canvas():
    return np.zeros((N, N), np.uint8)


def put(img, x, y, color):
    x, y = int(round(x)), int(round(y))
    if 0 <= x < N and 0 <= y < N:
        img[y, x] = color


def disc(img, cx, cy, r, color):
    yy, xx = np.mgrid[0:N, 0:N]
    img[(xx - cx) ** 2 + (yy - cy) ** 2 <= r * r + 0.5] = color


def ring(img, cx, cy, r0, r1, color):
    yy, xx = np.mgrid[0:N, 0:N]
    d = (xx - cx) ** 2 + (yy - cy) ** 2
    img[(d >= r0 * r0) & (d <= r1 * r1)] = color


def outline(img):
    """1px darkest outline around everything drawn (4 neighbours), the Terraria look."""
    filled = img > 0
    edge = np.zeros_like(filled)
    edge[1:, :] |= filled[:-1, :]
    edge[:-1, :] |= filled[1:, :]
    edge[:, 1:] |= filled[:, :-1]
    edge[:, :-1] |= filled[:, 1:]
    img[edge & ~filled] = OUTLINE
    return img


def shaded_orb(img, cx, cy, r, spin):
    """Ball lit from the top-left: bands from dark at the bottom-right to a white spot, two swirl arms on top."""
    disc(img, cx, cy, r, DARK)
    disc(img, cx - 1, cy - 1, r - 2, BASE)
    disc(img, cx - 2, cy - 2, r - 5, MID)
    disc(img, cx - 3, cy - 3, max(1, r - 8), LIGHT)
    disc(img, cx - 4, cy - 4, 1, WHITE)
    for arm in range(2):  # swirl arms, turned a bit each frame
        for t in np.linspace(0.15, 1, 18):
            a = spin + arm * math.pi + t * 3.2
            rr = r * t * 0.92
            put(img, cx + math.cos(a) * rr, cy + math.sin(a) * rr, LIGHT if t < 0.55 else MID)


def spark(img, x, y, color=LIGHT):
    """Small plus-shaped spark."""
    for dx, dy in ((0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)):
        put(img, x + dx, y + dy, color)
    put(img, x, y, WHITE)


def frame_orb(spin):
    img = canvas()
    shaded_orb(img, C, C, 11, spin)
    for k in range(2):  # 2 orbiting ghost sparks
        a = spin * 1.6 + k * math.pi
        spark(img, C + math.cos(a) * 17, C + math.sin(a) * 9)
    return outline(img)


def frame_compress():
    img = canvas()
    rnd = random.Random(2)
    for k in range(10):  # suction lines pulling inward
        a = k * math.tau / 10 + rnd.uniform(-0.15, 0.15)
        for t in np.linspace(13, 13 + rnd.randint(6, 11), 10):
            put(img, C + math.cos(a) * t, C + math.sin(a) * t, MID if t < 18 else BASE)
    shaded_orb(img, C, C, 8, 1.0)
    disc(img, C, C, 3, LIGHT)
    return outline(img)


def frame_flash():
    img = canvas()
    rnd = random.Random(3)
    for k in range(16):  # jagged spikes of the detonation
        a = k * math.tau / 16
        ln = 16 + rnd.randint(-2, 4)
        for t in np.linspace(9, ln, 12):
            put(img, C + math.cos(a) * t, C + math.sin(a) * t, MID if t > ln - 4 else LIGHT)
    disc(img, C, C, 12, MID)
    disc(img, C, C, 10, LIGHT)
    disc(img, C, C, 7, WHITE)
    return outline(img)


def frame_peak():
    """8-pronged shockwave of ectoplasm: tapered prongs, lighter toward the middle."""
    img = canvas()
    yy, xx = np.mgrid[0:N, 0:N]
    dx, dy = xx - C, yy - C
    r = np.hypot(dx, dy)
    a = np.arctan2(dy, dx)
    # distance in angle to the nearest of 8 prongs (one every 45 degrees, starting at 22.5 so it reads as an X and a +)
    prong = np.abs((a - math.pi / 8) % (math.pi / 4) - math.pi / 8)
    reach = 26
    width = 0.42 * (1 - r / reach)  # prongs get thinner toward the tip
    shape = ((prong < width) & (r < reach)) | (r < 11)
    img[shape] = BASE
    img[shape & ((prong < width * 0.55) | (r < 9))] = MID
    img[shape & ((prong < width * 0.25) | (r < 6))] = LIGHT
    img[r < 3.5] = WHITE
    return outline(img)


def frame_ring():
    """The blast hollows out into a ring of spirit fire: solid band, flame tongues on the outer edge."""
    img = canvas()
    yy, xx = np.mgrid[0:N, 0:N]
    r = np.hypot(xx - C, yy - C)
    a = np.arctan2(yy - C, xx - C)
    outer = 21 + 3.5 * np.clip(np.sin(a * 9), 0, None) ** 2 + 1.2 * np.sin(a * 23 + 1)
    band = (r >= 16) & (r <= outer)
    img[band] = BASE
    img[band & (r <= outer - 2.5)] = MID
    img[band & (r <= 18)] = LIGHT
    return outline(img)


def frame_embers():
    """The ring breaks into 6 ghostly embers flying outward, each with a short tail toward the center."""
    img = canvas()
    for k in range(6):
        a = k * math.tau / 6 + 0.3
        x, y = C + math.cos(a) * 22, C + math.sin(a) * 22
        for t in range(1, 6):  # tail
            put(img, x - math.cos(a) * t, y - math.sin(a) * t, MID if t < 3 else BASE)
        disc(img, x, y, 2, MID)
        put(img, x, y, LIGHT)
    return outline(img)


def frame_smoke():
    """Embers turn into lumps of dark lavender smoke (flat fills, a highlight on top)."""
    img = canvas()
    for k in range(6):
        a = k * math.tau / 6 + 0.45
        x, y = C + math.cos(a) * 21, C + math.sin(a) * 21 - 2
        disc(img, x, y, 3, DARK)
        disc(img, x + 2, y + 1, 2, DARK)
        disc(img, x - 1, y - 1, 1, BASE)
    return outline(img)


def frame_sparks():
    """Last frame: 4 tiny fading sparks."""
    img = canvas()
    for k in range(4):
        a = k * math.tau / 4 + 0.8
        x, y = C + math.cos(a) * 24, C + math.sin(a) * 24 - 3
        put(img, x, y, DARK)
        put(img, x + 1, y, OUTLINE)
    return img


FRAMES = [frame_orb(0.0), frame_orb(1.1), frame_compress(), frame_flash(), frame_peak(), frame_ring(),
          frame_embers(), frame_smoke(), frame_sparks()]


def to_rgba(img):
    out = np.zeros((N, N, 4), np.uint8)
    for idx, hexc in COLORS.items():
        out[img == idx] = [int(hexc[i:i + 2], 16) for i in (1, 3, 5)] + [255]
    return out.repeat(SCALE, 0).repeat(SCALE, 1)


strip = np.concatenate([to_rgba(f) for f in FRAMES], axis=1)
Image.fromarray(strip, "RGBA").save("Pokerraria/Assets/Moves/ShadowBall.png", optimize=True)
# Two frames loop while the ball flies to the target, then the explosion plays on it
open("Pokerraria/Assets/Moves/ShadowBall.txt", "w").write(f"Frames {len(FRAMES)}\nTravel 2\nTicks 4\nScale 1\n")

preview = Image.new("RGBA", (strip.shape[1], strip.shape[0]), (255, 0, 255, 255))
preview.alpha_composite(Image.fromarray(strip, "RGBA"))
preview.convert("RGB").save("art/vfx/sheets/shadow_ball_desenhado_por_codigo.png")
print("ShadowBall", len(FRAMES), strip.shape[1] // len(FRAMES), strip.shape[0])
